#!/usr/bin/env python3
import io,tarfile,pathlib
root=pathlib.Path(__file__).resolve().parent
exe=root/'f2_recover_sqlite_arm'
if not exe.is_file():raise SystemExit('Missing ARM executable')
staticexe=root/'f2_recover_sqlite_static_arm'
if not staticexe.is_file():raise SystemExit('Missing static ARM executable')
probe=root/'f2_display_probe'
if not probe.is_file():raise SystemExit('Missing display probe')
writer=root/'f2_xlsx_writer'
if not writer.is_file():raise SystemExit('Missing static XLSX writer')
head=exe.read_bytes()[:20]
if head[:4]!=b'\x7fELF' or head[4]!=1 or int.from_bytes(head[18:20],'little')!=40:raise SystemExit('Not ARM32 ELF')
control=b'Package: f2_service_diagnostic\nVersion: 1.0.12\nArchitecture: armv7l\nMaintainer: service\nDescription: F2 read-only diagnostic SQLite WAL\n'
postinst="#!/bin/sh\nUSB=/mnt/nand_disk\nLOG=\"$USB/F2_diagnostic_status.txt\"\nSYS=\"$USB/F2_machine_info.tsv\"\nif [ ! -d \"$USB\" ]; then exit 1; fi\nrm -f \"$USB/F2_passwords.txt\" \"$USB/F2_machine_report.xlsx\" \"$USB/F2_machine_info.tsv\" \"$USB/F2_settings.tsv\" \"$USB/F2_drink_statistics.tsv\" \"$USB/F2_statistics_sources.tsv\" \"$USB/F2_error_records.tsv\" \"$USB/F2_error_guide.tsv\" \"$USB/F2_code5_search.tsv\" \"$USB/F2_code5_logs.tsv\" \"$USB/F2_deep_forensics.tsv\"\nprintf 'Показатель\\tЗначение\\tПримечание\\n' > \"$SYS\"\nrow() {\n V=$(printf '%s' \"$2\" | tr '\\t\\r\\n' '   ' | cut -c1-500)\n printf '%s\\t%s\\t%s\\n' \"$1\" \"$V\" \"$3\" >> \"$SYS\"\n}\nrow 'Платформа' \"$(uname -m 2>/dev/null)\" 'Архитектура'\nrow 'Модель HMI' \"$(hostname 2>/dev/null)\" 'Системное имя'\nrow 'Ядро Linux' \"$(uname -r 2>/dev/null)\" 'Версия ядра'\nif [ -f /etc/os-release ]; then row 'Прошивка ОС' \"$(grep -m1 PRETTY_NAME /etc/os-release 2>/dev/null | cut -d= -f2- | tr -d '\"')\" 'Buildroot'; fi\nif [ -e /lib/ld-linux-armhf.so.3 ]; then\n EXE=/usr/local/bin/f2_recover_sqlite_arm\n row 'Системная библиотека' 'glibc' 'Загрузчик доступен'\nelse\n EXE=/usr/local/bin/f2_recover_sqlite_static_arm\n row 'Системная библиотека' 'uClibc/другая' 'Статическая ARM-программа'\nfi\nrow 'Диагностика, версия' '1.0.12' 'F2 Service Diagnostic'\nif [ -f /root/Hmi ]; then row 'Приложение HMI, байт' \"$(wc -c < /root/Hmi)\" 'Размер файла (версия неизвестна)'; fi\nif [ -f /opt/updateAssistant ]; then row 'Модуль обновления, байт' \"$(wc -c < /opt/updateAssistant)\" 'Размер файла (версия неизвестна)'; fi\nrow 'RAM всего, кБ' \"$(awk '/^MemTotal:/{print $2;exit}' /proc/meminfo)\" 'Оперативная память'\nrow 'RAM доступно, кБ' \"$(awk '/^MemAvailable:/{print $2;exit}' /proc/meminfo)\" 'Может отсутствовать в старом ядре'\nrow 'RAM свободно, кБ' \"$(awk '/^MemFree:/{print $2;exit}' /proc/meminfo)\" 'Свободная RAM'\nrow 'RAM занято приблизительно, кБ' \"$(awk '/^MemTotal:/{t=$2}/^MemFree:/{f=$2}END{if(t>0)print t-f}' /proc/meminfo)\" 'Всего минус MemFree (включая кеш)'\nrow 'HMI раздел, всего, кБ' \"$(df -k / 2>/dev/null | awk 'NR==2{print $2}')\" 'Внутренняя память'\nrow 'HMI раздел, занято, кБ' \"$(df -k / 2>/dev/null | awk 'NR==2{print $3}')\" 'Внутренняя память'\nrow 'HMI раздел, свободно, кБ' \"$(df -k / 2>/dev/null | awk 'NR==2{print $4}')\" 'Внутренняя память'\nrow 'HMI раздел, заполнено, %' \"$(df -k / 2>/dev/null | awk 'NR==2{print $5}')\" 'Внутренняя память'\nif [ -f /root/machine.db ]; then\n row 'База SQLite, байт' \"$(wc -c < /root/machine.db)\" 'Файл настроек'\n row 'SQLite режим журнала' \"$(od -An -tu1 -j 18 -N 2 /root/machine.db 2>/dev/null)\" '1 1 rollback, 2 2 WAL'\nfi\necho 'F2_PACKAGE_VERSION=1.0.12' > \"$LOG\"\necho \"SELECTED_EXECUTABLE=$EXE\" >> \"$LOG\"\n# Find additional SQLite databases without copying or modifying them.\nset --\nfor ROOT in /root /opt /var/lib /mnt; do\n [ -d \"$ROOT\" ] || continue\n for DB in $(find \"$ROOT\" -type f \\( -name '*.db' -o -name '*.sqlite' -o -name '*.sqlite3' \\) -size -20480k 2>/dev/null | head -n 24); do\n  [ \"$DB\" = /root/machine.db ] && continue\n  set -- \"$@\" \"$DB\"\n  [ \"$#\" -ge 12 ] && break\n done\n [ \"$#\" -ge 12 ] && break\ndone\necho \"ADDITIONAL_DATABASES=$#\" >> \"$LOG\"\n\"$EXE\" /root/machine.db \"$USB\" \"$@\" >> \"$LOG\" 2>&1\nRC=$?\nif [ \"$RC\" -eq 0 ]; then\n cat > \"$USB/F2_error_guide.tsv\" <<'F2_ERROR_GUIDE'\n№ в руководстве\tОтображаемая ошибка\tРусское описание\tОсновные проверки\n1\tHMI error\tСвязь дисплея и основной платы\tКабель HMI, соединения, плата\n2\tFridge error\tОшибка холодильника\tСвязь холодильника, питание, плата\n3\tThermoblock heating overtime\tПерегрев/задержка нагрева кофейного термоблока\tНагреватель, питание, управление\n4\tCoffee thermoblock NTC error\tДатчик температуры кофейного термоблока\tNTC, проводка, разъёмы\n5\tSteam thermoblock overtime\tНагрев парового термоблока не достиг цели\tНагреватель пара, питание\n6\tSteam thermoblock NTC error\tДатчик температуры парового термоблока\tNTC, проводка, разъёмы\n7\tBoiler heating overtime\tПревышено время нагрева бойлера\tБойлер, нагреватель\n8\tNTC error\tОшибка датчика температуры бойлера\tNTC бойлера, проводка\n9\tThermoblock water supply error\tОшибка подачи воды в термоблок\tВодоснабжение, расходомер, насос, тракт\n10\tBoiler water supply error\tОшибка подачи воды в бойлер\tКлапан, расходомер, насос\n11\tBrewer system error\tОшибка заварочного блока\tБлокировка, мотор привода, механизм\n12\tLack of water\tНедостаток воды при приготовлении\tПодача воды, насос, расходомер\n13\tLeft grinder error\tОшибка левой кофемолки\tЗасор, перегрузка, датчик Холла, плата\n14\tRight grinder error\tОшибка правой кофемолки\tЗасор, перегрузка, датчик Холла, плата\nF2_ERROR_GUIDE\n\n printf 'Файл\\tСтрока\\tМаркер\\tКонтекст\\n' > \"$USB/F2_code5_logs.tsv\"\n FILES=0\n for DIR in /var/log /root/log /root/logs /opt/log /opt/logs; do\n  if [ ! -d \"$DIR\" ]; then continue; fi\n  find \"$DIR\" -type f -size -2048k 2>/dev/null | while IFS= read -r F; do\n   case \"$F\" in *.log|*.txt|*.json|*.ini|*.csv) ;; *) continue;; esac\n   grep -in -m 5 'code5' \"$F\" 2>/dev/null | head -n 5 | while IFS= read -r MATCH; do\n    LINE=$(printf '%s' \"$MATCH\" | cut -d: -f1)\n    CONTENT=$(printf '%s' \"$MATCH\" | cut -d: -f2- | tr '\\t\\r\\n' '   ' | cut -c1-250)\n    printf '%s\\t%s\\tcode5\\t%s\\n' \"$F\" \"$LINE\" \"$CONTENT\" >> \"$USB/F2_code5_logs.tsv\"\n   done\n  done\n done\n /usr/local/bin/f2_xlsx_writer \"$USB/F2_machine_report.xlsx\" 'Паспорт HMI' \"$SYS\" 'Настройки' \"$USB/F2_settings.tsv\" 'Напитки' \"$USB/F2_drink_statistics.tsv\" 'Ошибки (сырые)' \"$USB/F2_error_records.tsv\" 'Справочник ошибок' \"$USB/F2_error_guide.tsv\" 'Поиск code5 в БД' \"$USB/F2_code5_search.tsv\" 'Поиск code5 логи' \"$USB/F2_code5_logs.tsv\" 'Глубокий поиск' \"$USB/F2_deep_forensics.tsv\" >> \"$LOG\" 2>&1\n RC=$?\n if [ \"$RC\" -eq 0 ]; then\n  rm -f \"$SYS\" \"$USB/F2_settings.tsv\" \"$USB/F2_drink_statistics.tsv\" \"$USB/F2_statistics_sources.tsv\"\n  echo 'OK: F2_machine_report.xlsx' >> \"$LOG\"\n else\n  echo 'ERROR: Excel report generation failed; TSV data retained' >> \"$LOG\"\n fi\nfi\n# Read-only compatibility assessment; never draw service passwords.\n/usr/local/bin/f2_display_probe \"$USB\" >> \"$LOG\" 2>&1\n{\n echo 'DISPLAY_TEST=READ_ONLY';\n echo 'QT_PROCESS=';\n ps 2>/dev/null | grep '[H]mi' | head -n 3;\n echo 'FRAMEBUFFER_DEVICES=';\n ls -l /dev/fb* 2>/dev/null;\n echo 'GRAPHICS_PROCESSES=';\n ps 2>/dev/null | grep -E '[q]t|[H]mi|[w]eston|[X]org|[u]pdateAssistant' | head -n 10;\n echo 'QT_ENVIRONMENT=';\n for proc in /proc/[0-9]*; do\n  [ -r \"$proc/cmdline\" ] || continue\n  if tr '\\\\0' ' ' < \"$proc/cmdline\" 2>/dev/null | grep -q '/root/Hmi'; then\n   tr '\\\\0' '\\\\n' < \"$proc/environ\" 2>/dev/null | grep -E '^(QT_QPA_PLATFORM|QWS_DISPLAY|DISPLAY|WAYLAND_DISPLAY)=' | head -n 8;\n  fi\n done;\n} > \"$USB/F2_display_environment.txt\" 2>&1\nsync\nexit \"$RC\"\n".encode()

def archive(entries):
 b=io.BytesIO()
 with tarfile.open(fileobj=b,mode='w:gz',format=tarfile.GNU_FORMAT) as tar:
  for name,data,mode in entries:
   t=tarfile.TarInfo(name);t.size=len(data);t.mode=mode;t.uid=0;t.gid=0;tar.addfile(t,io.BytesIO(data))
 return b.getvalue()
ct=archive([('./control',control,0o644),('./postinst',postinst,0o755)])
dt=archive([('./usr/local/bin/f2_recover_sqlite_arm',exe.read_bytes(),0o755),('./usr/local/bin/f2_recover_sqlite_static_arm',staticexe.read_bytes(),0o755),('./usr/local/bin/f2_xlsx_writer',writer.read_bytes(),0o755),('./usr/local/bin/f2_display_probe',probe.read_bytes(),0o755)])
out=root/'f2_service_diagnostic_1.0.12.drcoffee.ipk'
with tarfile.open(str(out),'w',format=tarfile.GNU_FORMAT) as tar:
 for name,data in [('./debian-binary',b'2.0\n'),('./control.tar.gz',ct),('./data.tar.gz',dt)]:
  t=tarfile.TarInfo(name);t.size=len(data);t.mode=0o644;tar.addfile(t,io.BytesIO(data))
print(out)
